sp_widget.client_script:
api.controller = function($scope) { 
    $scope.goToSubmitFeedback = function() { 
        var recordProducerSysId = '-1'; 
        var url = '/sp?id=sc_cat_item&sys_id=' + recordProducerSysId; 
        window.location.href = url; 
    }; 
};

sp_widget.css:
.custom-action-card-feedback {
    background: #f4f9f4; /* very light green background */
    border-radius: 12px;
    padding: 24px 20px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
    border: 1px solid #d8e8d8; /* subtle green border */
    text-align: center;
}

.custom-action-card-feedback h4 {
    margin-bottom: 16px;
    font-weight: 600;
    color: #3e5c3e; /* dark green-gray text */
    font-size: 18px;
}

.action-btn-feedback {
    background: #d7e8d0; /* light green button */
    color: #2e4032; /* dark green-gray text */
    padding: 10px 18px;
    font-size: 14px;
    border: none;
    border-radius: 6px;
    width: 100%;
    cursor: pointer;
    transition: background 0.2s ease;
}

.action-btn-feedback:hover {
    background: #c4dcc0; /* slightly darker on hover */
}
